import{_ as a,o as s,c as n,ah as o}from"./chunks/framework.BEhGrFfj.js";const r="/projects/ROSpider/en/jetson-nano-version/assets/image1.C6-fOXe5.png",l="/projects/ROSpider/en/jetson-nano-version/assets/image2.BsuRLvZl.png",h="/projects/ROSpider/en/jetson-nano-version/assets/image3.BikKmKCT.png",d="/projects/ROSpider/en/jetson-nano-version/assets/image4.BZf6Q0eB.png",e="/projects/ROSpider/en/jetson-nano-version/assets/image5.B76UPqCR.png",c="/projects/ROSpider/en/jetson-nano-version/assets/image6.CQfSxC25.png",t="data:image/png;base64,",p="/projects/ROSpider/en/jetson-nano-version/assets/image13.CEVxap2b.png",g="/projects/ROSpider/en/jetson-nano-version/assets/image15.BeqLSR-z.png",y=JSON.parse('{"title":"3. LiDAR Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3_LiDAR_Course.md","filePath":"docs/3_LiDAR_Course.md"}'),m={name:"docs/3_LiDAR_Course.md"};function u(k,i,b,v,F,f){return s(),n("div",null,[...i[0]||(i[0]=[o('<h1 id="_3-lidar-course" tabindex="-1">3. LiDAR Course <a class="header-anchor" href="#_3-lidar-course" aria-label="Permalink to &quot;3. LiDAR Course&quot;">​</a></h1><h2 id="_3-1-introduction-to-lidar" tabindex="-1">3.1 Introduction to LiDAR <a class="header-anchor" href="#_3-1-introduction-to-lidar" aria-label="Permalink to &quot;3.1 Introduction to LiDAR&quot;">​</a></h2><h3 id="_3-1-1-preface" tabindex="-1">3.1.1 Preface <a class="header-anchor" href="#_3-1-1-preface" aria-label="Permalink to &quot;3.1.1 Preface&quot;">​</a></h3><p>As a high-precision, high-speed remote sensing technology, LiDAR plays an important role in mapping, autonomous driving, environmental perception, and robot navigation. This document introduces the principles, components, working mechanisms, application areas, and advantages of LiDAR, as well as its development trends.</p><p>LiDAR plays a critical role in autonomous driving and intelligent transportation by detecting obstacles, pedestrians, and vehicles on the road in real-time, providing precise distance and position information. In terms of robot navigation and environmental perception, LiDAR provides robots with accurate maps and surrounding environment information. Additionally, LiDAR is widely used in 3D modeling, map making, safety monitoring, and remote sensing mapping.</p><img loading="lazy" height="330" width="611" class="common_img" src="'+r+'"><h3 id="_3-1-2-lidar-components-and-classification" tabindex="-1">3.1.2 LiDAR Components and Classification <a class="header-anchor" href="#_3-1-2-lidar-components-and-classification" aria-label="Permalink to &quot;3.1.2 LiDAR Components and Classification&quot;">​</a></h3><p>A LiDAR system consists of components such as a laser emitter, a receiver and photodetector, a scanning mechanism, and an angle resolution unit. The laser emitter generates the laser beam, the receiver and photodetector receive the reflected optical signals, the scanning mechanism scans the surrounding environment, and the angle resolution unit determines the position of the target object. Based on the scanning method, LiDAR can be functionally divided into the following categories:</p><ul><li><strong>Rotating LiDAR</strong>: By rotating the emitter or scanning mechanism, rotating LiDAR performs a full-range omnidirectional scan of the laser beam in the horizontal direction. They typically feature high scanning speeds and measurement precision, and are widely used in autonomous driving, 3D environmental modeling, and map-making.</li><li><strong>Solid-State LiDAR</strong>: Solid-state LiDAR uses solid-state laser emitters and requires no rotating parts. It is generally more compact, lightweight, and has lower power consumption. Solid-state LiDAR is suitable for application scenarios involving mobile devices, drones, and robots.</li><li><strong>Mechanical LiDAR</strong>: Mechanical LiDAR utilizes mechanical parts, such as rotating mirrors or rotating prisms, to achieve laser beam scanning. They usually offer long measurement distances and high measurement accuracy, but with slower scanning speeds. Mechanical LiDAR is widely used in topographic surveying, building scanning, and navigation.</li><li><strong>Phase-Modulated LiDAR</strong>: Phase-modulated LiDAR measures the distance between the target object and the radar by altering the phase of the laser beam. They typically possess high measurement accuracy and a large measurement range, making them widely used in map making, surveying, and industrial applications.</li><li><strong>Flash LiDAR</strong>: Flash LiDAR uses a single, brief, high-power laser pulse to illuminate the entire scene at once, and then captures the reflected optical signals through a receiver array. Featuring high speed and high resolution, it is suitable for applications like rapid scene capture and motion tracking.</li></ul><h2 id="_3-2-lidar-working-principles-and-ranging-methods" tabindex="-1">3.2 LiDAR Working Principles and Ranging Methods <a class="header-anchor" href="#_3-2-lidar-working-principles-and-ranging-methods" aria-label="Permalink to &quot;3.2 LiDAR Working Principles and Ranging Methods&quot;">​</a></h2><h3 id="_3-2-1-lidar-ranging" tabindex="-1">3.2.1 LiDAR Ranging <a class="header-anchor" href="#_3-2-1-lidar-ranging" aria-label="Permalink to &quot;3.2.1 LiDAR Ranging&quot;">​</a></h3><p>There are two common methods for LiDAR to determine the distance to a target: Triangulation and Time-of-Flight (ToF) ranging.</p><p>ToF ranging can be understood by referring to the diagram below. The LiDAR first shines light onto the object, which then reflects the light directly back to the LiDAR. The LiDAR calculates the time it takes for the light to return, multiplies this time by the speed of light, and divides the result by two to determine the distance between the object and the LiDAR.</p><img loading="lazy" class="common_img" src="'+l+'" style="width:600px;"><p>Triangulation can be understood by referring to the diagram below. During manufacturing, the LiDAR is adjusted so that the light does not shine directly onto the object, but rather at a specific angle. This angle is preset and remains constant during operation. By substituting this angle into trigonometric functions, the distance from the object to the LiDAR can be calculated.</p><img loading="lazy" class="common_img" src="'+h+'" style="width:600px;"><h3 id="_3-2-2-lidar-effects" tabindex="-1">3.2.2 LiDAR Effects <a class="header-anchor" href="#_3-2-2-lidar-effects" aria-label="Permalink to &quot;3.2.2 LiDAR Effects&quot;">​</a></h3><p>Refer to the diagram below to understand the effect of LiDAR. The LiDAR emits light that illuminates the surface of an object. When the LiDAR receives the light reflected from the object, the outline of the object is marked at the illuminated position.</p><img loading="lazy" class="common_img" src="'+d+'" style="width:600px;"><h2 id="_3-3-lidar-obstacle-avoidance" tabindex="-1">3.3 LiDAR Obstacle Avoidance <a class="header-anchor" href="#_3-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;3.3 LiDAR Obstacle Avoidance&quot;">​</a></h2><p>To understand the connection method for the app, please refer to <strong><a href="https://wiki.hiwonder.com/projects/ROSpider/en/jetson-nano-version/docs/1_ROSpider_User_Manual.html#app-installation-and-connection" target="_blank" rel="noreferrer">1. ROSpider User Manual\\1.3.3 App Installation and Connection</a></strong> for the relevant course.</p><h3 id="_3-3-1-activation-via-app" tabindex="-1">3.3.1 Activation via App <a class="header-anchor" href="#_3-3-1-activation-via-app" aria-label="Permalink to &quot;3.3.1 Activation via App&quot;">​</a></h3><ol><li>Open the app <strong>WonderNex</strong> and connect to ROSpider.</li><li>In the mode selection interface, tap <strong>Lidar</strong> to enter the operation interface for this feature.</li></ol><img loading="lazy" height="636" width="1365" class="common_img" src="'+e+'" style="width:600px;"><ol start="3"><li>Tap the switch button on the right side of <strong>Avoid obstacle</strong> to activate this feature.</li></ol><img loading="lazy" class="common_img" src="'+c+'" style="width:600px;"><h3 id="_3-3-2-activation-via-commands" tabindex="-1">3.3.2 Activation via Commands <a class="header-anchor" href="#_3-3-2-activation-via-commands" aria-label="Permalink to &quot;3.3.2 Activation via Commands&quot;">​</a></h3><ol><li>Start the robot and connect it to the remote control software NoMachine. For details on connecting to the remote desktop, refer to <strong><a href="https://wiki.hiwonder.com/projects/ROSpider/en/jetson-nano-version/docs/1_ROSpider_User_Manual.html#development-environment-setup" target="_blank" rel="noreferrer">1. ROSpider User Manual\\1.4 Development Environment Setup</a></strong>.</li><li>Click the icon <img loading="lazy" height="34" width="43" src="'+t+'"> on the system desktop to open the command line terminal.</li><li>Enter the command to stop the auto-start service and press <strong>Enter</strong>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Next, enter the command and press <strong>Enter</strong> to launch the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><ol start="5"><li>Open a new command line terminal, enter the command, and press <strong>Enter</strong> to access the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><ol start="6"><li>Then, in the current command line terminal, enter the command and press <strong>Enter</strong> to activate the LiDAR obstacle avoidance feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 1}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the command in the current command line terminal and press <strong>Enter</strong> to execute.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To exit the feature, press <strong>Ctrl + C</strong> directly in the terminal interface from step 4.</li></ol><h3 id="_3-3-2-program-outcome" tabindex="-1">3.3.2 Program Outcome <a class="header-anchor" href="#_3-3-2-program-outcome" aria-label="Permalink to &quot;3.3.2 Program Outcome&quot;">​</a></h3><p>During the use of the LiDAR obstacle avoidance function, the object to be detected must be higher than the horizontal scanning height of the LiDAR. This ensures that the LiDAR mounted on the robot can effectively scan its position information. As the hexapod robot walks forward and detects an obstacle, it will automatically turn to avoid it.</p><h2 id="_3-4-lidar-following" tabindex="-1">3.4 LiDAR Following <a class="header-anchor" href="#_3-4-lidar-following" aria-label="Permalink to &quot;3.4 LiDAR Following&quot;">​</a></h2><p>To understand the connection method for the app, please refer to <strong><a href="https://wiki.hiwonder.com/projects/ROSpider/en/jetson-nano-version/docs/1_ROSpider_User_Manual.html#app-installation-and-connection" target="_blank" rel="noreferrer">1. ROSpider User Manual\\1.3.3 App Installation and Connection</a></strong> for the relevant course.</p><h3 id="_3-4-1-activation-via-app" tabindex="-1">3.4.1 Activation via APP <a class="header-anchor" href="#_3-4-1-activation-via-app" aria-label="Permalink to &quot;3.4.1 Activation via APP&quot;">​</a></h3><ol><li>Open the app <strong>WonderNex</strong> and connect to ROSpider.</li><li>In the mode selection interface, tap <strong>Lidar</strong> to enter the operation interface for this feature.</li></ol><img loading="lazy" height="636" width="1365" class="common_img" src="'+e+'" style="width:600px;"><ol start="3"><li>Tap the switch button on the right side of <strong>Lidar following</strong> to activate this feature.</li></ol><img loading="lazy" class="common_img" src="'+p+'" style="width:600px;"><h3 id="_3-4-2-activation-via-commands" tabindex="-1">3.4.2 Activation via Commands <a class="header-anchor" href="#_3-4-2-activation-via-commands" aria-label="Permalink to &quot;3.4.2 Activation via Commands&quot;">​</a></h3><ol><li>Start the robot and connect it to the remote control software NoMachine. For details on connecting to the remote desktop, refer to <strong><a href="https://wiki.hiwonder.com/projects/ROSpider/en/jetson-nano-version/docs/1_ROSpider_User_Manual.html#development-environment-setup" target="_blank" rel="noreferrer">1. ROSpider User Manual\\1.4 Development Environment Setup</a></strong>.</li><li>Click the icon <img loading="lazy" height="34" width="43" src="'+t+'"> on the system desktop to open the command line terminal.</li><li>Enter the command to stop the auto-start service and press <strong>Enter</strong>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Next, enter the command and press <strong>Enter</strong> to launch the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><ol start="5"><li>Open a new command line terminal, enter the command, and press <strong>Enter</strong> to access the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><ol start="6"><li>Then, in the current command line terminal, enter the command and press <strong>Enter</strong> to activate the LiDAR following feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 2}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the command in the current command line terminal and press <strong>Enter</strong> to execute.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To exit the feature, press <strong>Ctrl + C</strong> directly in the terminal interface from step 4.</li></ol><h3 id="_3-4-2-program-outcome" tabindex="-1">3.4.2 Program Outcome <a class="header-anchor" href="#_3-4-2-program-outcome" aria-label="Permalink to &quot;3.4.2 Program Outcome&quot;">​</a></h3><p>During the use of the LiDAR following feature, the object to be detected must be higher than the horizontal scanning height of the LiDAR. This ensures that the LiDAR mounted on the robot can effectively scan its position information. The robot will then adjust its own position so that the distance between the body and the obstacle is constantly maintained at a certain range.</p><h2 id="_3-5-lidar-guarding" tabindex="-1">3.5 LiDAR Guarding <a class="header-anchor" href="#_3-5-lidar-guarding" aria-label="Permalink to &quot;3.5 LiDAR Guarding&quot;">​</a></h2><p>To understand the connection method for the app, please refer to <strong><a href="https://wiki.hiwonder.com/projects/ROSpider/en/jetson-nano-version/docs/1_ROSpider_User_Manual.html#app-installation-and-connection" target="_blank" rel="noreferrer">1. ROSpider User Manual\\1.3.3 App Installation and Connection</a></strong> for the relevant course.</p><h3 id="_3-5-1-activation-via-app" tabindex="-1">3.5.1 Activation via APP <a class="header-anchor" href="#_3-5-1-activation-via-app" aria-label="Permalink to &quot;3.5.1 Activation via APP&quot;">​</a></h3><ol><li>Open the app <strong>WonderNex</strong> and connect to ROSpider.</li><li>In the mode selection interface, tap <strong>Lidar</strong> to enter the operation interface for this feature.</li></ol><img loading="lazy" height="636" width="1365" class="common_img" src="'+e+'" style="width:600px;"><ol start="3"><li>Tap the switch button on the right side of <strong>Lidar guarding</strong> to activate this feature.</li></ol><img loading="lazy" class="common_img" src="'+g+'" style="width:600px;"><h3 id="_3-5-2-activation-via-commands" tabindex="-1">3.5.2 Activation via Commands <a class="header-anchor" href="#_3-5-2-activation-via-commands" aria-label="Permalink to &quot;3.5.2 Activation via Commands&quot;">​</a></h3><ol><li>Start the robot and connect it to the remote control software NoMachine. For details on connecting to the remote desktop, refer to <strong><a href="https://wiki.hiwonder.com/projects/ROSpider/en/jetson-nano-version/docs/1_ROSpider_User_Manual.html#development-environment-setup" target="_blank" rel="noreferrer">1. ROSpider User Manual\\1.4 Development Environment Setup</a></strong>.</li><li>Click the icon <img loading="lazy" height="34" width="43" src="'+t+'"> on the system desktop to open the command line terminal.</li><li>Enter the command to stop the auto-start service and press <strong>Enter</strong>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Next, enter the command and press <strong>Enter</strong> to launch the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><ol start="5"><li>Open a new command line terminal, enter the command, and press <strong>Enter</strong> to access the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><ol start="6"><li>Then, in the current command line terminal, enter the command and press <strong>Enter</strong> to activate the LiDAR guarding feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 3}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the command in the current command line terminal and press <strong>Enter</strong> to execute.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To exit the feature, press <strong>Ctrl + C</strong> directly in the terminal interface from step 4.</li></ol><h3 id="_3-5-2-program-outcome" tabindex="-1">3.5.2 Program Outcome <a class="header-anchor" href="#_3-5-2-program-outcome" aria-label="Permalink to &quot;3.5.2 Program Outcome&quot;">​</a></h3><p>During the use of the LiDAR guarding feature, the object to be detected must be higher than the horizontal scanning height of the LiDAR. This ensures that the LiDAR mounted on the robot can effectively scan its position information. The robot will then adjust the orientation of its body to face the obstacle, aligning the camera directly toward the obstacle.</p>',82)])])}const C=a(m,[["render",u]]);export{y as __pageData,C as default};
